INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('rev-1', 'Executive Director 1', 'المدير التنفيذي 1', 'Al-Jazeera Gulf Holdings W.L.L.', 'مجموعة الجزيرة الخليجية القابضة', 'Working with Awal Supplies streamlined our operations and exceeded delivery expectations.', 'العمل مع أوال للتوريدات ساهم في رفع كفاءة عملياتنا وتجاوز توقعاتنا في التسليم.', 5, true, 1, 2026, now() - interval '7 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'awal-supplies-insights-1', 'Awal Supplies Industry Brief #1: Torque Tool Calibration', 'تقرير أوال للتوريدات التخصصي #1: معايرة أدوات العزم', 'Key operational benchmarks and best practices from Awal Supplies in Sitra.', 'أبرز المعايير التشغيلية وأفضل الممارسات من أوال للتوريدات في Sitra.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Trusted distributor of certified industrial tools, PPE safety gear, and warehouse hardware serving contractors and retail buyers across Bahrain. Our Torque Tool Calibration division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"موزع معتمد للأدوات الصناعية ومعدات السلامة وتجهيزات المستودعات للمقاولين والأفراد في البحرين. يساعد قسم معايرة أدوات العزم المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>Trusted distributor of certified industrial tools, PPE safety gear, and warehouse hardware serving contractors and retail buyers across Bahrain.</p><p>Our Torque Tool Calibration division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>موزع معتمد للأدوات الصناعية ومعدات السلامة وتجهيزات المستودعات للمقاولين والأفراد في البحرين.</p><p>يساعد قسم معايرة أدوات العزم المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'products', '{"products","Sitra","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '9 days', true, now() - interval '9 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How do we engage Awal Supplies for a new project?', 'كيف يمكننا البدء بمشروع جديد مع أوال للتوريدات؟', 'Contact Awal Supplies at sales@awalsupplies.bh or submit an inquiry online; our team responds within one business day.', 'يمكنكم التواصل عبر sales@awalsupplies.bh أو إرسال طلب إلكتروني وسيرد فريق أوال للتوريدات خلال يوم عمل واحد.', 'general', true, 1, now()) ON CONFLICT (id) DO NOTHING;
